  '[{"id":"tc1","validation_type":"matching","expected_value":"Load a CSV into a DataFrame","description_en":"read_csv","description_id":"read_csv","points":25},{"id":"tc2","validation_type":"matching","expected_value":"Show the first rows","description_en":"head","description_id":"head","points":25},{"id":"tc3","validation_type":"matching","expected_value":"Summary statistics","description_en":"describe","description_id":"describe","points":25},{"id":"tc4","validation_type":"matching","expected_value":"Aggregate by a category","description_en":"groupby","description_id":"groupby","points":25}]',
